import {ROUTES,money,dateLabel} from './model.mjs';
import {scenarioTitle,visibleScenarios,planningChecks,recommendationFor} from './workspace-model.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=value=>new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(value));
const routeName=id=>ROUTES.find(r=>r.id===id)?.short||'Cape of Good Hope';
const modeIcon=id=>({ocean:'ship',rail:'train',multimodal:'mixed',air:'plane'})[ROUTES.find(r=>r.id===id)?.mode]||'route';
export function collectionView({records,history,query,starredOnly,canUndo},icon){
 const list=visibleScenarios(records,{query,starredOnly,history});
 const metrics=record=>`<div class="saved-metrics"><div><span>Logistics cost</span><strong>${money(record.cost)}</strong></div><div><span>Arrival</span><strong>${dateLabel(record.arrival,true)}</strong></div><div><span>Transport emissions</span><strong>${record.co2.toFixed(1)} <em>t CO₂e</em></strong></div></div>`;
 return `<section class="page-heading"><div><div class="eyebrow">${history?'YOUR DECISION TRAIL':'PLANNING COLLECTION'}</div><h1>${history?'Decision log':'Saved scenarios'}</h1><p>${history?'A local timeline of the scenarios kept in this workspace.':'Keep named snapshots, revisit assumptions and take your work with you.'}</p></div><button class="button primary" data-action="new-scenario">${icon('plus',16)} New scenario</button></section><section class="collection-tools panel" aria-label="Saved scenario tools"><label class="collection-search">${icon('search',17)}<input type="search" value="${esc(query)}" placeholder="Find a saved scenario…" aria-label="Search saved scenarios" data-focus="collection-search"></label><button class="button outline collection-star-filter" data-action="starred-filter" aria-pressed="${starredOnly}">${icon('star',15)} Starred</button><div class="collection-backup-actions"><button class="button quiet" data-action="export-backup" ${records.length?'':'disabled'}>${icon('download',15)} Export backup</button><button class="button outline" data-action="import-backup">${icon('upload',15)} Import</button></div></section><div class="collection-count"><span>${list.length} ${list.length===1?'scenario':'scenarios'}${records.length!==list.length?` of ${records.length}`:''}</span>${canUndo?'<button class="text-button" data-action="undo-delete">Undo deletion</button>':'<span>Snapshots keep the assumptions from the moment you saved.</span>'}</div>${list.length?history?`<div class="decision-timeline">${list.map(record=>`<article class="decision-record panel"><div class="decision-record-date">${icon('bookmark',16)}<time datetime="${esc(record.createdAt)}">${esc(time(record.createdAt))}</time><span>Snapshot</span></div><h2>${esc(scenarioTitle(record))}</h2><p class="decision-route">${esc(record.routeName)} · Baseline: ${esc(routeName(record.settings.baseline))}</p>${metrics(record)}<blockquote>${esc(record.reason)}</blockquote><div class="decision-actions"><button class="text-button" data-action="scenario-assumptions" data-id="${esc(record.id)}">Inspect saved assumptions ${icon('arrow',14)}</button><button class="text-button" data-action="export-decision" data-id="${esc(record.id)}">${icon('download',14)} Export brief</button></div></article>`).join('')}</div>`:`<div class="saved-list collection-grid">${list.map(record=>`<article class="saved-card panel"><div class="saved-card-top"><div class="saved-icon">${icon(modeIcon(record.routeId),22)}</div><div><span class="overline">SHP-2026-0842 · ${esc(time(record.createdAt))}</span><h2>${esc(scenarioTitle(record))}</h2><p class="saved-route-name">${esc(record.routeName)}</p></div><button class="icon-button scenario-star ${record.starred?'is-starred':''}" data-action="star-scenario" data-id="${esc(record.id)}" data-focus="star-${esc(record.id)}" aria-label="${record.starred?'Unstar':'Star'} ${esc(scenarioTitle(record))}" aria-pressed="${record.starred}">${icon('star',18)}</button></div>${metrics(record)}<blockquote>${esc(record.reason)}</blockquote><div class="saved-snapshot-meta">${icon('lock',13)} Snapshot · ${esc(routeName(record.settings.baseline))} baseline</div><div class="collection-card-actions"><div><button class="text-button" data-action="scenario-assumptions" data-id="${esc(record.id)}">Assumptions</button><button class="icon-button" data-action="rename-scenario" data-id="${esc(record.id)}" aria-label="Rename ${esc(scenarioTitle(record))}">${icon('edit',16)}</button><button class="icon-button" data-action="delete-scenario" data-id="${esc(record.id)}" aria-label="Delete ${esc(scenarioTitle(record))}">${icon('trash',16)}</button></div><button class="button outline" data-action="load" data-id="${esc(record.id)}">Open scenario ${icon('arrow',14)}</button></div></article>`).join('')}</div>`:`<div class="empty-state panel"><div class="empty-illustration">${icon(records.length?'search':'folder',36)}</div><h2>${records.length?'No scenarios match this view.':'Your first scenario starts here.'}</h2><p>${records.length?'Try another search or show all saved scenarios.':'Compare the routes and save an option with a reason. You can also import a scenario backup.'}</p><button class="button primary" ${records.length?'data-action="clear-collection-filters"':'data-action="nav" data-view="planner"'}>${records.length?'Show all scenarios':'Explore route scenarios'} ${icon('arrow',15)}</button></div>`}<div class="local-note">${icon('info',15)} Saved locally in this browser. Export a JSON backup to move the collection, or a text brief for one decision.</div>`;
}
export function checksView(route,settings,icon,open){
 const checks=planningChecks(route,settings),passed=checks.filter(c=>c.passed).length;
 return `<details class="planning-checks" data-planning-checks ${open?'open':''}><summary><strong>Planning checks</strong><span class="${passed===3?'good':'caution'}">${passed}/3 passed</span>${icon('down',14)}</summary><div>${checks.map(check=>`<div class="planning-check"><span class="${check.passed?'good':'caution'}">${icon(check.passed?'check':'alert',14)}</span><div><strong>${check.label}</strong><p>${check.value} <span>/ ${check.limit}</span></p></div><small class="${check.passed?'muted':'caution'}">${check.detail}</small></div>`).join('')}</div></details>`;
}
export function assumptionsView(record,current,icon){
 const fields=[['Route',record.routeName,ROUTES.find(r=>r.id===current.selected).name],['Budget',money(record.settings.budget),money(current.budget)],['Deadline',dateLabel(record.settings.deadline,true),dateLabel(current.deadline,true)],['CO₂e limit',record.settings.emissions+' t',current.emissions+' t'],['Fuel adjustment',record.settings.fuel+'%',current.fuel+'%'],['Port delay',record.settings.delay+'d',current.delay+'d'],['Priority',record.settings.priority,current.priority],['Baseline',routeName(record.settings.baseline),routeName(current.baseline)]];
 return `<div class="dialog-content"><p class="snapshot-intro">${icon('lock',16)} Saved values stay fixed when you change the planner.</p><h3>${esc(scenarioTitle(record))}</h3><p class="snapshot-subtitle">${esc(record.routeName)} · ${esc(time(record.createdAt))}</p><div class="assumption-table-scroll"><table class="assumption-table"><thead><tr><th>Assumption</th><th>Saved snapshot</th><th>Current planner</th></tr></thead><tbody>${fields.map(([label,saved,current])=>`<tr class="${saved!==current?'assumption-changed':''}"><th scope="row">${label}</th><td>${esc(saved)}</td><td>${esc(current)}${saved!==current?'<small>Changed</small>':''}</td></tr>`).join('')}</tbody></table></div><blockquote class="snapshot-reason">${esc(record.reason)}</blockquote></div><footer class="dialog-footer"><button class="button quiet" data-action="export-decision" data-id="${esc(record.id)}">${icon('download',15)} Export brief</button><button class="button primary" data-action="load" data-id="${esc(record.id)}">Load saved assumptions ${icon('arrow',15)}</button></footer>`;
}
export function recommendationView(settings,icon){
 const {weights,candidates}=recommendationFor(settings),best=candidates[0],labels=['Cost','Transit time','CO₂e'];
 return `<div class="dialog-content"><div class="recommendation-verdict"><span class="mode-tile">${icon(best?'check':'alert',23)}</span><div><h3>${best?esc(best.short):'No route meets every limit'}</h3><p>${candidates.length} of 6 routes meet the current budget, deadline and emissions limits.</p></div></div><p class="ranking-explanation">Eligible routes are compared using your <strong>${esc(settings.priority)}</strong> priority. A cheaper route that misses a limit is excluded first.</p>${settings.priority==='balanced'?`<div class="priority-weight-bar" role="img" aria-label="Cost ${weights[0]} percent, transit ${weights[1]} percent, emissions ${weights[2]} percent">${weights.map((weight,i)=>`<span class="weight-${i}" style="width:${weight}%"></span>`).join('')}</div><div class="priority-weights">${weights.map((weight,i)=>`<span><i class="weight-${i}"></i>${labels[i]} <strong>${weight}%</strong></span>`).join('')}</div>`:`<p class="priority-direct-note">Eligible routes are ordered by ${settings.priority==='time'?'calendar-day transit':settings.priority==='cost'?'total logistics cost':'transport emissions'}, lowest first. Weighted score breaks ties.</p>`}${best?`<div class="eligible-ranking">${candidates.map((route,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><div><strong>${esc(route.short)}</strong><small>${money(route.cost)} · ${route.days} days · ${route.co2.toFixed(1)} t CO₂e</small></div>${i===0?'<span class="pill positive">Best fit</span>':''}</div>`).join('')}</div>`:'<p class="no-ranking-note">Review your limits or test a different delivery window to create a viable set of alternatives.</p>'}<p class="ranking-footnote">The balanced priority compares normalized cost, time and emissions within the eligible set. This is a planning aid using illustrative data.</p></div><footer class="dialog-footer"><button class="button quiet" data-action="close">Back to planner</button>${best?`<button class="button primary" data-action="choose-explained" data-value="${best.id}">Inspect best fit ${icon('arrow',15)}</button>`:'<button class="button primary" data-action="constraints">Review limits</button>'}</footer>`;
}
